-- chair-step: inverse of read_lane_v2_b3_20_workbench_udt_workbook_snapshots — un-enrolls workbench.udt_workbook_snapshots from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'udt_workbook_snapshots' and is_active);
select iam.apply_rls('workbench', 'udt_workbook_snapshots', (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'udt_workbook_snapshots' and is_active), (select rls_variant from platform.entity_types where schema_name = 'workbench' and table_name = 'udt_workbook_snapshots' and is_active));
